import {ProcessContext} from "./processes";
import {finalise_userspace_proxy, mirror_source, MirrorSource, notify_mirror_change, type sync_members} from "./rpc";
import {absolute_from_source, absolute_path as resolve_absolute_path, join_path} from "../lib/path";

/**
 * Error thrown when a path is not found.
 *
 * @group Userspace
 * @category Filesystem
 */
export class PathNotFoundError extends Error {
    constructor(path: string) {
        super(`Path not found: ${path}`);
    }
}

/**
 * Error thrown when attempting to delete a non-empty directory without recursive flag.
 *
 * @group Userspace
 * @category Filesystem
 */
export class NonRecursiveDirectoryError extends Error {
    constructor(path: string) {
        super(`Refusing to delete non-empty directory: ${path}`);
    }
}

/**
 * Error thrown when attempting to move a directory into a non-empty destination.
 *
 * @group Userspace
 * @category Filesystem
 */
export class MoveDestinationDirectoryNotEmptyError extends Error {
    constructor(path: string) {
        super(`Destination directory is not empty: ${path}`);
    }
}

/**
 * Error thrown when attempting to write to a read-only path, or when attemping to write to a protected path without privilege.
 *
 * @group Userspace
 * @category Filesystem
 */
export class ReadOnlyError extends Error {
    constructor(path: string) {
        super(`Path is read-only: ${path}`);
    }
}

/**
 * Error thrown when attempting to read a protected file without privilege.
 *
 * @group Userspace
 * @category Filesystem
 */
export class ProtectedFileReadError extends Error {
    constructor(path: string) {
        super(`Path is protected and cannot be read: ${path}`);
    }
}

/**
 * Where programs keep state of their own, in a directory per program named after the program's identity (see {@link Kernel.get_private_storage_path}).
 * Userspace can neither read nor change it, apart from each program's own directory.
 */
export const PRIVATE_STORAGE_ROOT = "/var/lib/private";

/**
 * Kernel only. Directories userspace can't change (each one and everything under it), as only the kernel or a kernel function the user allows may.
 * /usr/lib holds what installed packages ship, which their programs in /usr/bin trust.
 */
export const WRITE_PROTECTED_PATHS: readonly string[] = ["/sys", "/boot", "/etc/services/privileged", "/etc/ssh", "/bin", "/usr/bin", "/usr/lib", PRIVATE_STORAGE_ROOT];

/**
 * Kernel only. Directories whose contents userspace can't read. Listing each directory itself is allowed (e.g. which programs have private storage), reading anything under it isn't.
 */
export const READ_PROTECTED_PATHS: readonly string[] = ["/etc/ssh", PRIVATE_STORAGE_ROOT];

const is_within = (absolute_path: string, dir: string): boolean => absolute_path === dir || absolute_path.startsWith(`${dir}/`);

/**
 * Kernel only. Whether userspace is refused changing an absolute path.
 * @param private_storage The process's own private storage (see {@link Kernel.get_private_storage_path}), which it may change.
 */
export const is_write_protected = (absolute_path: string, private_storage: string | null = null): boolean => {
    if (private_storage !== null && is_within(absolute_path, private_storage)) {
        return false;
    }

    return WRITE_PROTECTED_PATHS.some((protected_path) => is_within(absolute_path, protected_path));
};

/**
 * Kernel only. Whether userspace is refused reading an absolute path.
 * @param private_storage The process's own private storage (see {@link Kernel.get_private_storage_path}), which it may read.
 */
export const is_read_protected = (absolute_path: string, private_storage: string | null = null): boolean => {
    if (private_storage !== null && is_within(absolute_path, private_storage)) {
        return false;
    }

    return READ_PROTECTED_PATHS.some((protected_path) => absolute_path.startsWith(`${protected_path}/`));
};

/**
 * Event types emitted after filesystem operations.
 *
 * @group Userspace
 * @category Filesystem
 */
export enum FSEventType {
    READING_FILE,
    WROTE_FILE,
    DELETED_FILE,
    MOVED_FILE,
    SET_READONLY,

    LISTING_DIR,
    MADE_DIR,
    DELETED_DIR,
    MOVED_DIR,

    REMOVED_SET_CWD,
    REMOVED_GETTING_CWD,

    SET_HOME,
    GETTING_HOME,
    SET_ROOT,
    GETTING_ROOT,

    CHECKING_EXISTS,
    CHECKING_DIR_EXISTS,
}

// TODO: ensure all functions fire these events (opfs doesnt at all yet!)

/**
 * Handler type for filesystem events.
 * @param data Various string data related to the event, but most likely a path.
 * @param fs The filesystem instance emitting the event.
 *
 * @group Userspace
 * @category Filesystem
 */
export type FSEventHandler = (data: string, fs: AbstractFileSystem) => void;

/**
 * How the RPC layer accesses the filesystem's userspace proxy: these members read synchronously, everything else goes to the kernel.
 * @hidden
 */
export const USERSPACE_FILESYSTEM_ANNOTATIONS = {
    get_unique_fs_type_name: "constant",
    get_cwd: "mirrored",
    get_home: "mirrored",
    get_root: "mirrored",
    join: join_path,
    absolute: absolute_from_source,
} as const;

/**
 * Interface for interacting with the chosen filesystem implementation from userspace.
 *
 * For the privileged API, see {@link AbstractFileSystem}.
 *
 * @group Userspace
 * @category Filesystem
 */
export interface UserspaceFileSystem {
    /** @hidden */
    readonly [sync_members]?: (member: keyof typeof USERSPACE_FILESYSTEM_ANNOTATIONS) => void;
    get_unique_fs_type_name(): string;
    erase_all(): Promise<void>;
    purge_cache(smart?: boolean): void;
    read_file(path: string, as_uint?: boolean): Promise<string | Uint8Array>;
    write_file(path: string, data: string | Uint8Array, force?: boolean): Promise<void>;
    delete_file(path: string): Promise<void>;
    move_file(path: string, new_path: string): Promise<void>;
    list_dir(path: string, dirs_first?: boolean): Promise<string[]>;
    make_dir(path: string): Promise<void>;
    delete_dir(path: string, recursive?: boolean): Promise<void>;
    move_dir(src: string, dest: string, force_move_inside?: boolean): Promise<void>;
    set_readonly(path: string, readonly: boolean): Promise<void>;
    is_readonly(path: string): Promise<boolean>;
    /**
     * Whether the kernel protects a path from this program, so changing it (or reading it, with access "read") needs a kernel func the user allows.
     * Unlike {@link is_readonly}, this is about the path itself rather than a file's read-only flag. A program's own private storage is never protected from it.
     */
    is_protected(path: string, access?: "write" | "read"): Promise<boolean>;
    exists(path: string): Promise<boolean>;
    dir_exists(path: string): Promise<boolean>;
    join(base_dir: string, ...paths: string[]): string;
    absolute(path: string): string;
    get_cwd(): string;
    get_home(): string;
    get_root(): string;
}

// TODO: could protect erase_all but then also need to check recursive deletion, doesnt really gain much

/**
 * Interface for interacting with a filesystem implementation.
 *
 * For the userspace API, see {@link UserspaceFileSystem}.
 *
 * @group Kernel (Privileged)
 * @category Filesystem
 */
export abstract class AbstractFileSystem implements MirrorSource {
    readonly [mirror_source] = true as const;

    //TODO: dry

    // note some members are conventionally private with _ prefix to allow implementations to access them
    // they wont be exposed to userspace though

    _initialised: (() => void);
    #initialise_promise = new Promise<void>((resolve) => {
        this._initialised = resolve;
    });

    wait_until_initialised(): Promise<void> {
        return this.#initialise_promise;
    }

    readonly #cache: Map<string, { readonly: boolean, content: string | Uint8Array, as_uint: boolean }> = new Map();
    readonly #callbacks: Map<FSEventType, FSEventHandler[]> = new Map();

    _root = "/";
    _home = "/home";

    abstract get_unique_fs_type_name(): string;
    abstract erase_all(): Promise<void>;

    purge_cache(smart = false): void {
        if (smart) {
            for (const path in this.#cache) {
                if (!this.exists_direct(path)) {
                    this.#cache.delete(path);
                }
            }
        } else {
            this.#cache.clear();
        }
    }

    force_remove_from_cache(path: string): void {
        this.#cache.delete(path);
    }


    register_callback(event_type: FSEventType, callback: FSEventHandler): () => void {
        // if there are no callbacks for this event type, create an empty array
        if (!this.#callbacks.has(event_type)) {
            this.#callbacks.set(event_type, []);
        }

        // add callback to array
        this.#callbacks.get(event_type)!.push(callback);

        // return function to remove callback
        return () => {
            this.#callbacks.get(event_type)!.splice(this.#callbacks.get(event_type)!.indexOf(callback), 1);
        }
    }

    _call_callbacks(event_type: FSEventType, data: string): void {
        // call all callbacks
        for (const callback of this.#callbacks.get(event_type) ?? []) {
            callback(data, this);
        }
    }


    abstract read_file_direct(path: string, as_uint: boolean): Promise<string | Uint8Array>;
    abstract write_file_direct(path: string, data: string | Uint8Array): Promise<void>;
    abstract delete_file_direct(path: string): Promise<void>;
    // does not check if destination exists
    abstract move_file_direct(src: string, new_path: string): Promise<void>;
    abstract set_readonly_direct(path: string, readonly: boolean): Promise<void>;
    abstract is_readonly_direct(path: string): Promise<boolean>;


    async read_file(path: string, as_uint = false): Promise<string | Uint8Array> {
        // prevent prototype pollution

        this._call_callbacks(FSEventType.READING_FILE, path);

        // check if file is in cache and still exists, as well as if it's the correct type
        const cached = this.#cache.get(path);
        if (cached && await this.exists(path) && cached.as_uint === as_uint) {
            return this.#cache.get(path)!.content;
        }

        // if not, read it from disk and cache it
        const content = await this.read_file_direct(path, as_uint);
        this.#cache.set(path, { readonly: await this.is_readonly(path), content, as_uint });
        return content;
    }

    async write_file(path: string, data: string | Uint8Array, force = false): Promise<void> {
        // check if file is readonly
        let readonly = false;
        if (await this.exists(path)) {
            readonly = await this.is_readonly(path);
            
            if (!force && readonly) {
                throw new ReadOnlyError(path);
            }
        }

        // write to disk and cache
        this.#cache.set(path, { readonly, content: data, as_uint: data instanceof Uint8Array });
        await this.write_file_direct(path, data);
        this._call_callbacks(FSEventType.WROTE_FILE, path);
    }

    async delete_file(path: string): Promise<void> {
        // delete from cache and disk
        if (this.#cache.has(path)) {
            this.#cache.delete(path);
        }
        await this.delete_file_direct(path);
        this._call_callbacks(FSEventType.DELETED_FILE, path);
    }

    // does not check if destination exists
    async move_file(path: string, new_path: string): Promise<void> {
        // move in cache and disk
        this.#cache.set(new_path, this.#cache.get(path)!);
        this.#cache.delete(path);
        await this.move_file_direct(path, new_path);
        this._call_callbacks(FSEventType.MOVED_FILE, path);
    }

    async set_readonly(path: string, readonly: boolean): Promise<void> {
        // check if file exists
        if (!await this.exists(path)) {
            throw new PathNotFoundError(path);
        }

        // set readonly in cache and disk
        const entry = this.#cache.get(path);
        if (entry) {
            entry.readonly = readonly;
            this.#cache.set(path, entry);
        } else {
            this.#cache.set(path, {readonly, content: await this.read_file(path), as_uint: false});
        }

        await this.set_readonly_direct(path, readonly);
        this._call_callbacks(FSEventType.SET_READONLY, path);
    }

    async is_readonly(path: string): Promise<boolean> {
        // check if file exists
        if (!await this.exists(path)) {
            throw new PathNotFoundError(path);
        }

        // check if file is in cache
        const cached = this.#cache.get(path);
        if (cached) {
            return cached.readonly;
        }

        // if not, check on disk (cannot cache as would need to read content, causes recursive call)
        return this.is_readonly_direct(path);
    }


    abstract list_dir(path: string, dirs_first?: boolean): Promise<string[]>;
    // (recursive)
    abstract make_dir(path: string): Promise<void>;
    abstract delete_dir_direct(path: string, recursive: boolean): Promise<void>;
    abstract move_dir_direct(src: string, dest: string, force_move_inside: boolean): Promise<void>;

    async delete_dir(path: string, recursive = false): Promise<void> {
        await this.delete_dir_direct(path, recursive);

        // smart purge cache
        this.purge_cache(true);
    }

    async move_dir(src: string, dest: string, force_move_inside = false): Promise<void> {
        await this.move_dir_direct(src, dest, force_move_inside);

        // smart purge cache
        this.purge_cache(true);
    }

    get_home(): string {
        this._call_callbacks(FSEventType.GETTING_HOME, this._home);
        return this._home;
    }

    set_home(path: string): void {
        this._home = path;
        notify_mirror_change(this);
        this._call_callbacks(FSEventType.SET_HOME, path);
    }

    get_root(): string {
        this._call_callbacks(FSEventType.GETTING_ROOT, this._root);
        return this._root;
    }

    set_root(path: string): void {
        this._root = path;
        notify_mirror_change(this);
        this._call_callbacks(FSEventType.SET_ROOT, path);
    }


    abstract exists_direct(path: string): Promise<boolean>;
    abstract dir_exists(path: string): Promise<boolean>;

    async exists(path: string): Promise<boolean> {
        // check if file is in cache
        if (this.#cache.has(path)) {
            return true;
        }

        // if not, check if it exists on disk
        this._call_callbacks(FSEventType.CHECKING_EXISTS, path);
        return this.exists_direct(path);
    }

    absolute(path: string, cwd?: string): string {
        return resolve_absolute_path(path, {root: this._root, home: this._home, cwd});
    }

    join(base_dir: string, ...paths: string[]): string {
        return join_path(base_dir, ...paths);
    }

    /**
     * @param get_private_storage Gives the process's own private storage, which it may read and change. Asked on each check, as the kernel may only know who the process is once its program is found.
     */
    static create_userspace_proxy(fs: AbstractFileSystem, process: ProcessContext, get_private_storage: () => string | null = () => null): UserspaceFileSystem {
        const self = fs;
        const proxy = Object.create(null);

        // write protect certain kernel secured paths
        const check_path_for_writing = (path: string): string => {
            const absolute_path = self.absolute(path, process.cwd);

            // TODO: allow priv programs to add to protection
            if (is_write_protected(absolute_path, get_private_storage())) {
                throw new ReadOnlyError(absolute_path);
            }

            return absolute_path;
        };

        // read protect even more locked down paths
        const check_path_for_reading = (path: string): string => {
            const absolute_path = self.absolute(path, process.cwd);

            if (is_read_protected(absolute_path, get_private_storage())) {
                throw new ProtectedFileReadError(absolute_path);
            }

            return absolute_path;
        }

        Object.defineProperties(proxy, {
            get_unique_fs_type_name: { value: () => self.get_unique_fs_type_name(), enumerable: true },
            erase_all: { value: () => self.erase_all(), enumerable: true },
            purge_cache: { value: (smart?: boolean) => self.purge_cache(smart), enumerable: true },
            read_file: { value: (path: string, as_uint?: boolean) => self.read_file(check_path_for_reading(path), as_uint), enumerable: true },
            list_dir: { value: (path: string, dirs_first?: boolean) => self.list_dir(check_path_for_reading(path), dirs_first), enumerable: true },
            exists: { value: (path: string) => self.exists(self.absolute(path, process.cwd)), enumerable: true },
            dir_exists: { value: (path: string) => self.dir_exists(self.absolute(path, process.cwd)), enumerable: true },
            is_readonly: {
                value: async (path: string) => {
                    try {
                        check_path_for_writing(path);
                    } catch (e) {
                        if (e instanceof ReadOnlyError) {
                            return true;
                        }

                        throw e;
                    }

                    return await self.is_readonly(self.absolute(path, process.cwd));
                },
                enumerable: true
            },
            is_protected: {
                value: async (path: string, access: "write" | "read" = "write") => {
                    try {
                        if (access === "read") {
                            check_path_for_reading(path);
                        } else {
                            check_path_for_writing(path);
                        }
                    } catch (e) {
                        if (e instanceof ReadOnlyError || e instanceof ProtectedFileReadError) {
                            return true;
                        }

                        throw e;
                    }

                    return false;
                },
                enumerable: true
            },
            join: { value: (base: string, ...paths: string[]) => self.join(base, ...paths), enumerable: true },
            absolute: { value: (path: string) => self.absolute(path, process.cwd), enumerable: true },
            get_home: { value: () => self.get_home(), enumerable: true },
            get_root: { value: () => self.get_root(), enumerable: true },
            write_file: {
                value: (path: string, data: string | Uint8Array, force?: boolean) =>
                    self.write_file(check_path_for_writing(path), data, force),
                enumerable: true
            },
            delete_file: {
                value: (path: string) => self.delete_file(check_path_for_writing(path)),
                enumerable: true
            },
            move_file: {
                value: (path: string, new_path: string) => {
                    return self.move_file(check_path_for_writing(path), check_path_for_writing(new_path));
                },
                enumerable: true
            },
            make_dir: {
                value: (path: string) => self.make_dir(check_path_for_writing(path)),
                enumerable: true
            },
            delete_dir: {
                value: (path: string, recursive?: boolean) => self.delete_dir(check_path_for_writing(path), recursive),
                enumerable: true
            },
            move_dir: {
                value: (src: string, dest: string, move_inside?: boolean) => {
                    return self.move_dir(check_path_for_writing(src), check_path_for_writing(dest), move_inside);
                },
                enumerable: true
            },
            set_readonly: {
                value: (path: string, readonly: boolean) => self.set_readonly(check_path_for_writing(path), readonly),
                enumerable: true
            },

            // helper for compatability
            get_cwd: { value: () => self.absolute(process.cwd), enumerable: true },
        });

        return finalise_userspace_proxy(proxy, USERSPACE_FILESYSTEM_ANNOTATIONS, [
            fs,
            process
        ]);
    }
}

